  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
@media (prefers-color-scheme: light) {
  :root {
    --bg: #f5f6fa;
    --surface: #ffffff;
    --surface-2: #eef1f7;
    --line: #d8dde9;
    --text: #141826;
    --muted: #586176;
    --accent: #3b52d9;
    --accent-hover: #2e42b8;
    --on-accent: #ffffff;
