    --shadow: 0 1px 2px rgba(20, 24, 38, .08), 0 8px 24px rgba(20, 24, 38, .08);
  }
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--text); font: 15px/1.55 var(--font); }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
h1 { font-size: 1.5rem; line-height: 1.25; margin: 0 0 .5rem; }
.muted { color: var(--muted); }
.num { text-align: right; font-variant-numeric: tabular-nums; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px; }

/* Controls */
input, select, textarea, button { font: inherit; color: var(--text); }
input, select, textarea {
  background: var(--surface-2); border: 1px solid var(--line); border-radius: 8px; padding: .55rem .7rem; width: 100%;
}
input:focus-visible, select:focus-visible, textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 0; border-color: var(--accent); }
::placeholder { color: var(--muted); opacity: 1; }
button {
  cursor: pointer; border: 1px solid transparent; border-radius: 8px; padding: .5rem .95rem; font-weight: 600;
  background: var(--accent); color: var(--on-accent); transition: background .15s, transform .05s;
}
button:hover { background: var(--accent-hover); }
button:active { transform: translateY(1px); }
button:disabled { opacity: .55; cursor: not-allowed; }
button.secondary { background: var(--surface-2); color: var(--text); border-color: var(--line); }
button.secondary:hover { background: var(--line); }
button.danger { background: transparent; color: var(--danger); border-color: var(--danger); }
button.danger:hover { background: var(--danger-bg); }
button.linklike { background: none; color: var(--accent); padding: 0; border: 0; font-weight: 500; }
form.inline { display: inline; }

/* Header */
.topbar {
  position: sticky; top: 0; z-index: 10; height: var(--header-h); display: flex; align-items: center; justify-content: space-between;
  gap: 1rem; padding: 0 1rem; background: color-mix(in srgb, var(--bg) 88%, transparent); backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.brand { display: inline-flex; align-items: center; gap: .55rem; font-weight: 700; letter-spacing: .01em; color: var(--text); }
.brand:hover { text-decoration: none; }
.brand-mark { width: 1.35rem; height: 1.35rem; border-radius: 6px; background: linear-gradient(135deg, var(--accent), #b892ff); }
.topbar nav { display: flex; align-items: center; gap: 1rem; flex-wrap: wrap; justify-content: flex-end; }
.balance {
  display: inline-flex; align-items: center; gap: .35rem; background: var(--surface); border: 1px solid var(--line);
  border-radius: 999px; padding: .15rem .75rem; font-weight: 600; font-variant-numeric: tabular-nums;
}
.balance::before { content: "Balance"; color: var(--muted); font-weight: 500; font-size: .8rem; }

main { padding: 1rem; }

/* Auth cards */
.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); }
.narrow { max-width: 25rem; margin: 3rem auto; }
.card form p { margin: 0 0 1rem; display: grid; gap: .3rem; }
.card label { font-weight: 600; font-size: .9rem; }
.card .helptext, .card form ul { color: var(--muted); font-size: .8rem; margin: .2rem 0 0; padding-left: 1.1rem; }
.card form > button { width: 100%; padding: .65rem; }
.errorlist { color: var(--danger); font-size: .85rem; padding-left: 1.1rem; margin: 0; }
.card .alt { margin: 1rem 0 0; text-align: center; color: var(--muted); }

/* App layout */
.layout { display: grid; grid-template-columns: 17rem minmax(0, 1fr); gap: 1rem; height: calc(100dvh - var(--header-h) - 2rem); max-width: 80rem; margin: 0 auto; }
.sidebar { display: flex; flex-direction: column; gap: .75rem; min-height: 0; padding-right: 1rem; border-right: 1px solid var(--line); }
.sidebar > form button { width: 100%; }
.sidebar ul { list-style: none; margin: 0; padding: 0; overflow: auto; min-height: 0; display: grid; gap: .15rem; align-content: start; }
.sidebar li a {
