{% load money %}
{% block title %}{{ conversation.title|default:"Darkchat" }}{% endblock %}
{% block content %}
<div class="layout">
  <aside class="sidebar" aria-label="Conversations">
    <form method="post" action="{% url 'new_conversation' %}">{% csrf_token %}<button>+ New chat</button></form>
    <ul>
      {% for c in conversations %}
        <li class="{% if conversation and c.pk == conversation.pk %}active{% endif %}"><a href="{% url 'conversation' c.pk %}" {% if conversation and c.pk == conversation.pk %}aria-current="page"{% endif %}>{{ c.title }}</a></li>
      {% empty %}<li class="muted" style="padding:.45rem .65rem">No chats yet</li>{% endfor %}
    </ul>
  </aside>

  <section class="chat">
  {% if not conversation %}
    <div class="empty">
      <h2>Chat with any model. Pay for what you use.</h2>
      <p>Every reply shows exactly what it cost. Start a new chat to begin.</p>
      <div class="models" aria-label="Available models">
        {% for m in models %}
          <div><span><strong>{{ m.display_name }}</strong> <span class="muted">· {{ m.get_provider_display }}</span></span>
          <span class="muted">${{ m.input_price_micros_per_mtok|price_per_mtok }} in / ${{ m.output_price_micros_per_mtok|price_per_mtok }} out per 1M tokens</span></div>
        {% endfor %}
      </div>
      <form method="post" action="{% url 'new_conversation' %}">{% csrf_token %}<button>Start a new chat</button></form>
    </div>
  {% else %}
    <div class="convhead">
      <form method="post" action="{% url 'rename' conversation.pk %}">{% csrf_token %}
        <input name="title" value="{{ conversation.title }}" maxlength="200" aria-label="Chat title"><button class="secondary">Rename</button></form>
      <form method="post" action="{% url 'delete' conversation.pk %}" class="inline" onsubmit="return confirm('Delete this chat?')">{% csrf_token %}
        <button class="danger">Delete</button></form>
    </div>
    <div class="messages" id="messages" aria-label="Messages">
      {% for m in chat_messages %}
        <article class="msg {{ m.role }} {% if m.status == 'failed' or m.status == 'cancelled' %}failed{% endif %}">
          <div class="who">{% if m.role == "user" %}You{% else %}{{ m.model.display_name|default:"Assistant" }}{% endif %}</div>
          {% if m.reasoning %}<details class="reasoning"><summary>Reasoning</summary>{{ m.reasoning }}</details>{% endif %}
          <div class="body">{{ m.content }}</div>
          {% if m.error %}<div class="notice">{{ m.error }}</div>{% endif %}
          {% if m.role == "assistant" %}<div class="meta"><span>{{ m.input_tokens }} in / {{ m.output_tokens }} out · ${{ m.cost_micros|usd:6 }}</span>{% if m.content %}<button type="button" class="copy">Copy</button>{% endif %}</div>{% endif %}
        </article>
      {% empty %}
        <div class="empty" id="empty-hint"><h2>Ask anything</h2><p>Pick a model below and send your first message.</p></div>
      {% endfor %}
    </div>
    <div id="error" role="alert"></div>
    <div class="composer-wrap">
      <form class="composer" id="composer" method="post" action="{% url 'send' conversation.pk %}">
        {% csrf_token %}
        <textarea name="content" id="content" rows="1" placeholder="Message" aria-label="Message" required></textarea>
        <div class="row">
          <select name="model" id="model" aria-label="Model">
            {% for m in models %}
              <option value="{{ m.pk }}" {% if m.pk == conversation.model_id %}selected{% endif %}>{{ m.display_name }} · {{ m.get_provider_display }} · ${{ m.input_price_micros_per_mtok|price_per_mtok }}/${{ m.output_price_micros_per_mtok|price_per_mtok }} per 1M</option>
            {% endfor %}
          </select>
          <span class="hint">Enter to send · Shift+Enter for a new line</span>
          <button id="send">Send</button>
        </div>
      </form>
    </div>
  {% endif %}
  </section>
</div>

{% if conversation %}
<script>
(function () {
  const form = document.getElementById("composer"), box = document.getElementById("messages"),
        err = document.getElementById("error"), input = document.getElementById("content"),
        btn = document.getElementById("send"), balance = document.querySelector(".balance");
  const usd = (m, p) => (m / 1e6).toFixed(p);
  const toBottom = () => { box.scrollTop = box.scrollHeight; };
  const modelName = () => { const o = form.model.options[form.model.selectedIndex]; return o ? o.text.split(" · ")[0] : "Assistant"; };

  function el(tag, cls, text) { const n = document.createElement(tag); if (cls) n.className = cls; if (text !== undefined) n.textContent = text; return n; }
  function message(role, who) {
    const hint = document.getElementById("empty-hint"); if (hint) hint.remove();
    const root = el("article", "msg " + role), body = el("div", "body");
    root.append(el("div", "who", who), body); box.appendChild(root); toBottom();
    return { root, body };
  }
  function attachCopy(container, body) {
    const b = el("button", "copy", "Copy"); b.type = "button"; container.appendChild(b); wireCopy(b, body);
  }
  function wireCopy(b, body) {
    b.addEventListener("click", async () => {
      try { await navigator.clipboard.writeText(body.textContent); b.textContent = "Copied"; }
      catch (_) { b.textContent = "Press Ctrl/Cmd+C"; }
      setTimeout(() => { b.textContent = "Copy"; }, 1500);
    });
  }
  // Wire copy buttons on server-rendered replies.
  box.querySelectorAll(".msg.assistant").forEach(m => { const b = m.querySelector(".copy"); if (b) wireCopy(b, m.querySelector(".body")); });

  function grow() { input.style.height = "auto"; input.style.height = Math.min(input.scrollHeight, 192) + "px"; }
  input.addEventListener("input", grow);
  input.addEventListener("keydown", e => { if (e.key === "Enter" && !e.shiftKey && !e.isComposing) { e.preventDefault(); form.requestSubmit(); } });
  toBottom();

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    err.textContent = "";
    const text = input.value.trim();
    if (!text) return;
    const body = new FormData(form);
    btn.disabled = true; btn.textContent = "Sending…";
    const restore = () => { btn.disabled = false; btn.textContent = "Send"; input.focus(); };
    let res;
    try { res = await fetch(form.action, { method: "POST", body, credentials: "same-origin" }); }
    catch (_) { err.textContent = "Couldn't reach the server. Check your connection and try again."; restore(); return; }
    if (!res.ok) {
      let msg = "Something went wrong."; try { msg = (await res.json()).error || msg; } catch (_) {}
      err.textContent = msg; restore(); return;
    }
    message("user", "You").body.textContent = text;
    input.value = ""; grow();
    const out = message("assistant", modelName());
    out.body.classList.add("thinking");
    const textNode = document.createTextNode(""); out.body.append(textNode);
    box.setAttribute("aria-busy", "true");
    let details = null, reasoningNode = null;
    const meta = el("div", "meta"); out.root.append(meta);
    const firstToken = () => out.body.classList.remove("thinking");
    const handle = (ev) => {
      if (ev.t === "reasoning") {
        if (!details) {
          details = el("details", "reasoning"); details.append(el("summary", "", "Reasoning")); reasoningNode = document.createTextNode(""); details.append(reasoningNode);
          out.root.insertBefore(details, out.body);
        }
        reasoningNode.data += ev.v;
      } else if (ev.t === "text") { firstToken(); textNode.data += ev.v; }
      else if (ev.t === "done") {
        firstToken();
        meta.append(el("span", "", ev.input + " in / " + ev.output + " out · $" + usd(ev.cost, 6)));
        if (textNode.data) attachCopy(meta, out.body);
        if (ev.error) { out.root.insertBefore(el("div", "notice", ev.error), meta); out.root.classList.add("failed"); }
        if (balance) balance.textContent = "$" + usd(ev.balance, 4);
      }
      toBottom();
    };
    try {
      const reader = res.body.getReader(), dec = new TextDecoder(); let buf = "";
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buf += dec.decode(value, { stream: true });
        let i; while ((i = buf.indexOf("\n")) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (line) handle(JSON.parse(line)); }
      }
    } catch (_) { err.textContent = "Connection lost before the reply finished."; }
    firstToken(); box.removeAttribute("aria-busy"); restore();
  });
})();
</script>
{% endif %}
{% endblock %}
EOF
