import httpx, capture_proxy as cp
P = "Explain in detail how TCP congestion control works."
def run(label, name, url, body):
    p = cp.PROVIDERS[name]; h = {**p["headers"](cp.KEYS[name]), "Content-Type": "application/json"}
    r = httpx.post(url, headers=h, json=body, timeout=120)
    try: j = r.json()
    except ValueError: j = {}
    if r.status_code != 200:
        print(f"{label:38} HTTP {r.status_code} {cp.redact(json.dumps(j.get('error', j)))[:110]}"); return
    if name == "openai": u = j["usage"]; c = j["choices"][0]["message"]; out = (u["completion_tokens"], u.get("completion_tokens_details", {}).get("reasoning_tokens"), len(c.get("content") or ""), len(c.get("reasoning_content") or ""), j["choices"][0]["finish_reason"])
    elif name == "anthropic": u = j["usage"]; txt = "".join(b.get("text", "") for b in j["content"] if b["type"] == "text"); th = "".join(b.get("thinking", "") for b in j["content"] if b["type"] == "thinking"); out = (u["output_tokens"], None, len(txt), len(th), j["stop_reason"])
    else: u = j["usageMetadata"]; c = j["candidates"][0]; txt = "".join(x.get("text", "") for x in c["content"].get("parts", [])); out = (u.get("candidatesTokenCount"), u.get("thoughtsTokenCount"), len(txt), 0, c.get("finishReason"))
    print(f"{label:38} HTTP 200  (out_tokens, reasoning_tokens, answer_chars, reasoning_chars, finish) = {out}")
oa = p = cp.PROVIDERS["openai"]["chat_url"]; an = cp.PROVIDERS["anthropic"]["chat_url"]; go = cp.PROVIDERS["google"]["chat_url"]
